create table if not exists public."CNC_calibrations" (id uuid primary key default gen_random_uuid(), material text, tool text, machine text, operation text, spindle_rpm numeric, feed_rate numeric, comments text, created_at timestamptz default now()); create table if not exists public.cnc_machines (id uuid primary key default gen_random_uuid(), name text unique not null, n_max numeric, vf_max numeric, safety_n numeric, safety_vf numeric, created_at timestamptz default now()); alter table public."CNC_calibrations" enable row level security; alter table public.cnc_machines enable row level security; create policy if not exists "CNC read" on public."CNC_calibrations" for select to anon using (true); create policy if not exists "CNC insert" on public."CNC_calibrations" for insert to anon with check (true); create policy if not exists cnc_machines_read on public.cnc_machines for select to anon using (true); create policy if not exists cnc_machines_insert on public.cnc_machines for insert to anon with check (true); grant usage on schema public to anon, authenticated; grant select,insert on public."CNC_calibrations", public.cnc_machines to anon, authenticated; notify pgrst, 'reload schema';